            .no-print { display: none !important; }
            .menu-cards-container { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }
            .menu-card { page-break-inside: avoid; border: 1px solid #000; box-shadow: none; background: #fff; }
        }
    </style>
</head>
<body>

    <div class="no-print">
        <h1>Pop-Up Menu Hub</h1>

        <div class="dashboard">
            <div class="dashboard-item">Total Menu Items<span id="globalCount">0</span></div>
            <div class="dashboard-item">Total Est. Profit<span id="globalProfit">$0.00</span></div>
        </div>

        <button class="btn" onclick="addDish()">+ Add New Dish</button>

        <div id="editorContainer"></div>
    </div>

    <div class="section">
        <h2 class="no-print" style="margin-bottom:15px; font-size:1.2rem;">Live Menu Cards</h2>
        <div class="menu-cards-container" id="cardsContainer"></div>
        <div class="action-grid no-print" style="margin-top: 15px;">
            <button class="btn btn-print" onclick="window.print()">Print Cards</button>
            <button class="btn btn-secondary" onclick="copyAllBriefs()">Copy Master Brief</button>
        </div>
    </div>

    <div class="section no-print">
        <h2 style="margin-bottom:10px; font-size:1.2rem;">Master Text Brief</h2>
        <div class="brief-box" id="masterBriefText">No items added yet.</div>
    </div>

    <script>
        // Array to hold state locally without relying on data backends or external libs
        let menuItems = [
            {
                id: '1',
                name: 'Crispy Pork Belly Bao',
                hook: '24-hour braised pork, pickled cucumber, and hoisin drizzle in a fluffy steamed bun.',
                servings: 30,
                allergens: 'Gluten, Soy, Sesame',
                cost: 2.25,
                price: 8.50
            },
            {
                id: '2',
                name: 'Spicy Dan Dan Noodles',
                hook: 'Szechuan pepper minced beef, preserved vegetables, and house chili oil over wheat noodles.',
                servings: 25,
                allergens: 'Gluten, Peanuts, Soy',
                cost: 1.80,
                price: 12.00
            }
        ];

        // Safe evaluation function executing natively to avoid loading external math engines
        function safeNum(val) {
            const parsed = parseFloat(val);
            return isNaN(parsed) || parsed < 0 ? 0 : parsed;
        }

        function addDish() {
            const newId = Date.now().toString();
            menuItems.push({
                id: newId,
                name: '',
                hook: '',
                servings: 20,
                allergens: '',
                cost: 0,
                price: 0
            });
            render();
            document.getElementById(`name-${newId}`).focus();
        }

        function removeDish(id) {
            menuItems = menuItems.filter(item => item.id !== id);
            render();
        }

        function updateField(id, field, value) {
            const item = menuItems.find(item => item.id === id);
            if (item) {
                if (['servings', 'cost', 'price'].includes(field)) {
                    item[field] = safeNum(value);
                } else {
                    item[field] = value;
                }
                // Partial DOM rendering updates metrics & preview layouts instantly without whole-app stutter
                renderCalculationsAndPreviews();
            }
        }

        function renderCalculationsAndPreviews() {
            let totalMenuProfit = 0;
            let masterBrief = "";

            menuItems.forEach(item => {
                const costPct = item.price > 0 ? ((item.cost / item.price) * 100).toFixed(1) : '0.0';
                const profitPer = Math.max(0, item.price - item.cost);
                const itemTotalProfit = profitPer * item.servings;
                totalMenuProfit += itemTotalProfit;

                // Update Local Editor Component Metrics inline
                const costPctEl = document.getElementById(`calc-pct-${item.id}`);
                const profPerEl = document.getElementById(`calc-per-${item.id}`);
                const totalProfEl = document.getElementById(`calc-tot-${item.id}`);

                if (costPctEl) costPctEl.innerText = `${costPct}%`;
                if (profPerEl) profPerEl.innerText = `$${profitPer.toFixed(2)}`;
                if (totalProfEl) totalProfEl.innerText = `$${itemTotalProfit.toFixed(2)}`;

                // Update Viewable Menu Card component details
                const cardName = document.getElementById(`card-name-${item.id}`);
                const cardHook = document.getElementById(`card-hook-${item.id}`);
                const cardPrice = document.getElementById(`card-price-${item.id}`);
                const cardAllergens = document.getElementById(`card-allergens-${item.id}`);

                if (cardName) cardName.innerText = item.name || 'Untitled Dish';
                if (cardHook) cardHook.innerText = item.hook || 'No description provided.';
                if (cardPrice) cardPrice.innerText = `$${item.price.toFixed(2)}`;

                if (cardAllergens) {
                    if (item.allergens.trim()) {
                        cardAllergens.innerText = `Contains: ${item.allergens}`;
                        cardAllergens.style.display = 'inline-block';
                    } else {
                        cardAllergens.style.display = 'none';
                    }
                }

                // Append item to the growing Master Copyable Text Brief
                masterBrief += `DISH: ${item.name || 'Untitled'}\n`;
                masterBrief += `PRICE: $${item.price.toFixed(2)}\n`;
                masterBrief += `HOOK: ${item.hook || 'N/A'}\n`;
                masterBrief += `ALLERGENS: ${item.allergens || 'None declared'}\n`;
                masterBrief += `--- PROFIT METRICS ---\n`;
                masterBrief += `Food Cost: ${costPct}% ($${item.cost.toFixed(2)}/serv)\n`;
                masterBrief += `Margin/Serv: $${profitPer.toFixed(2)}\n`;
                masterBrief += `Est. Profit (${item.servings} serv): $${itemTotalProfit.toFixed(2)}\n\n`;
                masterBrief += `========================================\n\n`;
            });

            // Update Master Dashboard numbers
            document.getElementById('globalCount').innerText = menuItems.length;
            document.getElementById('globalProfit').innerText = `$${totalMenuProfit.toFixed(2)}`;

            // Update Master Brief Block text
            document.getElementById('masterBriefText').innerText = masterBrief.trim() || "No items added yet.";
        }

        function copyAllBriefs() {
            const text = document.getElementById('masterBriefText').innerText;
            navigator.clipboard.writeText(text).then(() => {
                alert('Master brief copied to clipboard!');
            }).catch(() => {
                alert('Copy failed. Please manually highlight text from the box below.');
            });
        }

        function render() {
            const editorContainer = document.getElementById('editorContainer');
            const cardsContainer = document.getElementById('cardsContainer');

            let editorHTML = '';
            let cardsHTML = '';

            menuItems.forEach((item, index) => {
                // Generate Form Input Components dynamically
                editorHTML += `
                    <div class="dish-manager-card">
                        <div class="dish-header">
                            <h3>Dish #${index + 1} Editor</h3>
                            <button class="btn btn-danger" onclick="removeDish('${item.id}')" style="width:auto; padding: 4px 10px; font-size:0.8rem; margin:0;">Remove</button>
                        </div>
                        <div class="form-group">
                            <label>Dish Name</label>
                            <input type="text" id="name-${item.id}" value="${item.name}" oninput="updateField('${item.id}', 'name', this.value)" placeholder="e.g., Crispy Pork Belly Bao">
                        </div>
                        <div class="form-group">
                            <label>The Hook (Short Description)</label>
                            <textarea oninput="updateField('${item.id}', 'hook', this.value)" placeholder="Short sensory description...">${item.hook}</textarea>
                        </div>
                        <div class="grid-3">
                            <div class="form-group">
                                <label>Servings</label>
                                <input type="number" value="${item.servings}" oninput="updateField('${item.id}', 'servings', this.value)" min="0">
                            </div>
                            <div class="form-group">
                                <label>Cost ($)</label>
                                <input type="number" step="0.01" value="${item.cost}" oninput="updateField('${item.id}', 'cost', this.value)" min="0">
                            </div>
                            <div class="form-group">
                                <label>Price ($)</label>
                                <input type="number" step="0.01" value="${item.price}" oninput="updateField('${item.id}', 'price', this.value)" min="0">
                            </div>
                        </div>
                        <div class="form-group">
                            <label>Allergens</label>
                            <input type="text" value="${item.allergens}" oninput="updateField('${item.id}', 'allergens', this.value)" placeholder="e.g., Nuts, Gluten">
                        </div>
                        <div class="dish-metrics">
                            <div>Cost Pct<span id="calc-pct-${item.id}">0%</span></div>
                            <div>Profit/Serv<span id="calc-per-${item.id}">$0.00</span></div>
                            <div>Total Profit<span id="calc-tot-${item.id}">$0.00</span></div>
                        </div>
                    </div>
                `;

                // Generate Matching Output Card Previews
                cardsHTML += `
                    <div class="menu-card" id="card-${item.id}">
                        <div class="menu-title" id="card-name-${item.id}">Dish Name</div>
                        <div class="menu-hook" id="card-hook-${item.id}">Description</div>
                        <div class="menu-price" id="card-price-${item.id}">$0.00</div>
                        <div class="menu-allergens" id="card-allergens-${item.id}">Allergens</div>
                    </div>
                `;
            });

            editorContainer.innerHTML = editorHTML;
            cardsContainer.innerHTML = cardsHTML;

            // Trigger internal balance math checks after rebuilding layout steps
            renderCalculationsAndPreviews();
        }

        // Initialize display pipelines with mockup defaults
        render();
    </script>
</body>
</html>

