        body { background: var(--bg); color: var(--text); padding: 10px; max-width: 800px; margin: 0 auto; padding-bottom: 60px; }
        .no-print h1 { font-size: 1.6rem; text-align: center; margin: 15px 0; }
        .section { background: var(--card-bg); padding: 15px; border-radius: 8px; border: 1px solid var(--border); margin-bottom: 15px; }
        .btn { background: var(--primary); color: white; border: none; padding: 12px; font-weight: bold; border-radius: 6px; cursor: pointer; width: 100%; margin-bottom: 10px; }
        .dish-card { background: #fff; border: 1px solid var(--border); padding: 15px; border-radius: 8px; margin-bottom: 15px; }
        .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 10px 0; }
        input, textarea { width: 100%; padding: 8px; border: 1px solid var(--border); border-radius: 4px; }
        .menu-preview-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 15px; }
        .menu-card { border: 2px dashed #9ca3af; padding: 15px; text-align: center; background: #fffdf9; min-height: 150px; display: flex; flex-direction: column; align-items: center; justify-content: center; }
